Q: SwiftUI ScrollView: GeometryReader + PreferenceKey Issues A: <p>Instead of using a <code>PreferenceKey</code>, it is usually much simpler just to update a state variable.</p>
<p>However, in the case here, tracking might not be necessary at all. You currently have a <code>LazyVStack</code> which has pinned headers, but it only contains one giant <code>Section</code>, inside which you are showing multiple <code>MockLeagueSection</code>. You then do all the work of switching the content of the pinned header yourself. This is the reason why you are trying to track, which league section is showing at the top.</p>
<p>An alternative way to implement would be to use a separate <code>Section</code> for each <code>MockLeagueSection</code>. This way, the pinned headers take care of themselves and you do not need to do any tracking at all.</p>
<p>The updated example below shows it working. You will notice that it is significantly less code than before. A few notes:</p>
<ul>
<li><p>A section header is now pushed away when a new header is scrolled up. This is different to the way the headers were being swapped before, but it might be acceptable anyway.</p>
</li>
<li><p>The border is shown in red, to make it easier to see. I think you were trying to show a border around the scrolled content that had rounded corners at the top (which stayed fixed) and rounded corners at the bottom (which moved with the content). To achieve the same thing, the top part of the border is shown as an overlay over the <code>ScrollView</code>, the bottom part of the border is shown as an overlay over the <code>LazyVStack</code>. Each of these two borders has its own mask, to control the part that is visible. The masks overlap, to give the impression of a continuous border.</p>
</li>
<li><p>You were previously ignoring the bottom safe area edge for the <code>ScrollView</code>, so that the clip shape also included the safe area inset. However, this meant adding bottom padding to the scrolled content, to allow it to scroll past the bottom safe area inset. You were using 100 points of padding (fixed). To allow the bottom padding to be kept to the minimum necessary, the size of the bottom safe area inset can be measured using a <code>GeometryReader</code>.</p>
</li>
</ul>
<p>Actually, a bit of tracking may be necessary after all, because of the way the pinned header is styled. Previously, only the pinned header at the top of the scrolled content had a divider below it, the section headers that were part of the scrolled content did not have dividers below them.</p>
<p>To show a divider below the pinned header in the same way, the section header can be factored out into a separate view and <code>.onGeometryChange</code> can be used to detect, when it is the top-most header in the <code>ScrollView</code>. This is when the y-coordinate of its frame is near to 0 in the coordinate space of the <code>ScrollView</code>. The divider can then be shown when it is detected that the header is currently the pinned header.</p>
<p>Using <code>frame(in: .scrollView)</code> requires iOS 17. If you need to support iOS 16 then a named coordinate space can be used instead.</p>
<pre class="lang-swift prettyprint-override"><code>struct CustomStyleTest: View {
    @Environment(\.colorScheme) private var colorScheme
    private let sections: [MockLeagueSection] = MockLeagueSection.sampleData

    var body: some View {
        GeometryReader { geo in
            ScrollView(showsIndicators: false) {
                customSectionsContent
                    .padding(.bottom, max(geo.safeAreaInsets.bottom, 20))
            }
            .clipShape(
                .rect(topLeadingRadius: 30, topTrailingRadius: 30)
            )
            .overlay {
                containerShape
                    .strokeBorder(.red)
                    .mask(alignment: .top) {
                        Color.black.frame(height: 300)
                    }
            }
            .ignoresSafeArea(edges: .bottom)
            .padding(.horizontal, 12)
            .navigationTitle(&quot;Custom Style Test&quot;)
            .navigationBarTitleDisplayMode(.inline)
        }
    }

    private var customSectionsContent: some View {
        LazyVStack(spacing: 0, pinnedViews: [.sectionHeaders]) {
            ForEach(Array(sections.enumerated()), id: \.element.id) { _, section in
                Section {
                    customSectionRow(section: section)
                } header: {
                    sectionHeader(section: section)
                }
            }
        }
        .background {
            containerShape.fill(containerFill)
        }
        .overlay {
            containerShape
                .strokeBorder(.red)
                .mask {
                    Color.black.padding(.top, 50)
                }
        }
    }

    private func customSectionRow(section: MockLeagueSection) -&gt; some View {
        VStack(spacing: 0) {
            ForEach(Array(section.games.enumerated()), id: \.element.id) { gameIndex, game in
                mockGameRow(game: game)
                if gameIndex &lt; section.games.count - 1 {
                    Divider()
                        .padding(.vertical, 2)
                }
            }
        }
        .padding()
    }

    private func sectionHeader(section: MockLeagueSection) -&gt; some View {
        LeagueSectionHeader(section: section)
            .background { containerFill }
            .background(.background)
    }

    private func mockGameRow(game: MockGame) -&gt; some View {
        VStack(alignment: .leading, spacing: 6) {
            HStack {
                Text(game.statusText)
                    .font(.footnote.weight(.semibold))
                    .foregroundStyle(game.isLive ? .red : .secondary)
                Spacer()
            }

            HStack(spacing: 12) {
                VStack(alignment: .leading, spacing: 6) {
                    teamLine(abbreviation: game.awayAbbreviation, name: game.awayName)
                    teamLine(abbreviation: game.homeAbbreviation, name: game.homeName)
                }

                Spacer(minLength: 12)

                VStack(alignment: .trailing, spacing: 6) {
                    Text(&quot;\(game.awayScore)&quot;)
                        .font(.title3.weight(.semibold))
                        .foregroundStyle(game.isLive ? .primary : .secondary)
                    Text(&quot;\(game.homeScore)&quot;)
                        .font(.title3.weight(.semibold))
                        .foregroundStyle(game.isLive ? .primary : .secondary)
                }
            }
        }
        .padding(.vertical, 10)
    }

    private func teamLine(abbreviation: String, name: String) -&gt; some View {
        HStack(spacing: 8) {
            Text(abbreviation)
                .font(.headline.weight(.semibold))
                .foregroundStyle(.primary)
                .frame(width: 60, alignment: .leading)
            Text(name)
                .font(.subheadline)
                .foregroundStyle(.secondary)
        }
    }

    private var containerShape: RoundedRectangle {
        RoundedRectangle(cornerRadius: 30, style: .continuous)
    }

    private var containerFill: LinearGradient {
        if colorScheme == .dark {
            return LinearGradient(
                colors: [
                    Color.white.opacity(0.07),
                    Color.white.opacity(0.07)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        } else {
            return LinearGradient(
                colors: [
                    Color.white.opacity(0.95),
                    Color(white: 0.965).opacity(0.92)
                ],
                startPoint: .topLeading,
                endPoint: .bottomTrailing
            )
        }
    }
}

struct LeagueSectionHeader: View {
    fileprivate let section: MockLeagueSection
    @State private var isTop = false

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Divider()
                .padding(.bottom, 4)
            sectionHeaderLabel(for: section)
                .padding()
        }
        .overlay(alignment: .bottom) {
            if isTop {
                Divider()
            }
        }
        .animation(.easeInOut, value: isTop)
        .onGeometryChange(for: Bool.self) { geo in
            abs(geo.frame(in: .scrollView).minY) &lt; 1
        } action: { isTopOfScrollView in
            isTop = isTopOfScrollView
        }
    }

    private func sectionHeaderLabel(for section: MockLeagueSection) -&gt; some View {
        HStack(spacing: 8) {
            Image(systemName: section.symbolName)
                .font(.caption.weight(.semibold))
                .foregroundStyle(.secondary)
            Text(section.title)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.primary)
            Image(systemName: &quot;chevron.right&quot;)
                .font(.caption.weight(.bold))
                .foregroundStyle(.secondary)
        }
    }
}

// + MockLeagueSection, MockGame (as before)
// - CustomStyleTestSectionMarker, CustomStyleTestSectionMarkerPreferenceKey (obsolete)
</code></pre>
